        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Horizontal colored bars on the top and bottom edges act as beam origins.
    # They project the lone interior/object color perpendicular to the edge,
    # stopping at an existing object; a touched object becomes the collision color 4.
    bars = []
    bar_colors = set()
    for edge, row_index in (("top", 0), ("bottom", h - 1)):
        row = grid[row_index]
