                c += 1
                continue
            color = row[c]
            end = c + 1
            while end < w and row[end] == color:
                end += 1
            if end - c >= 2:
                bars.append((edge, c, end, color))
                bar_colors.add(color)
            c = end

    object_colors = [v for v in counts if v != bg and v not in bar_colors]
    if len(object_colors) != 1:
        return out
    fill_color = object_colors[0]

    for edge, start, end, _ in bars:
        if edge == "top":
            rows = range(1, h)
            step = 1
        else:
            rows = range(h - 2, -1, -1)
            step = -1
