 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    # Find equal-length, same-colored runs on opposite borders.
    def runs_on_edge(which):
        if which == "top":
            vals = grid[0]
        elif which == "bottom":
            vals = grid[h - 1]
        elif which == "left":
            vals = [grid[r][0] for r in range(h)]
        else:
            vals = [grid[r][w - 1] for r in range(h)]
        result = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
                result.append((i, j, color))
            i = j
        return result

    pairs = []
    for side_a, side_b in (("top", "bottom"), ("left", "right")):
        for a0, a1, ac in runs_on_edge(side_a):
            for b0, b1, bc in runs_on_edge(side_b):
                if ac == bc and a1 - a0 == b1 - b0:
                    pairs.append((side_a, side_b, a0, b0, a1 - a0))

    if not pairs:
        return out

    guide_colors = {grid[0][c] for c in range(w) if grid[0][c] != bg}
    guide_colors |= {grid[h - 1][c] for c in range(w) if grid[h - 1][c] != bg}
    guide_colors |= {grid[r][0] for r in range(h) if grid[r][0] != bg}
    guide_colors |= {grid[r][w - 1] for r in range(h) if grid[r][w - 1] != bg}
    marker_colors = [x for x in counts if x != bg and x not in guide_colors]

    for side_a, side_b, start_a, start_b, length in pairs:
        # For every rare marker whose coordinate lies in one of the paired
        # guide spans, draw its ray to that border and the matching full ray
        # at the same offset from the opposite guide.
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color in guide_colors or color not in marker_colors:
                    continue
                if side_a in ("top", "bottom"):
                    if start_a <= c < start_a + length:
                        src, other, offset = side_a, side_b, c - start_a
                    elif start_b <= c < start_b + length:
                        src, other, offset = side_b, side_a, c - start_b
                    else:
                        continue
                    # Marker-side ray heads to its own boundary.
                    step = -1 if src == "top" else 1
                    rr = r + step
                    while 0 <= rr < h:
                        if grid[rr][c] != bg:
                            break
                        out[rr][c] = color
                        rr += step
                    # Mark the marker as a collision/endpoint unless it is
                    # already part of a connected marker pattern.
                    out[r][c] = 4
                    paired_col = (start_b if other == side_b else start_a) + offset
                    for rr in range(h):
                        if grid[rr][paired_col] == bg:
                            out[rr][paired_col] = color
                else:
                    if start_a <= r < start_a + length:
                        src, other, offset = side_a, side_b, r - start_a
                    elif start_b <= r < start_b + length:
                        src, other, offset = side_b, side_a, r - start_b
                    else:
                        continue
                    step = -1 if src == "left" else 1
                    cc = c + step
                    while 0 <= cc < w:
                        if grid[r][cc] != bg:
                            break
                        out[r][cc] = color
                        cc += step
                    out[r][c] = 4
                    paired_row = (start_b if other == side_b else start_a) + offset
                    for cc in range(w):
                        if grid[paired_row][cc] == bg:
                            out[paired_row][cc] = color
    return out
