 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(side):
        if side == "top":
            vals = grid[0]
        elif side == "bottom":
            vals = grid[h - 1]
        elif side == "left":
            vals = [grid[r][0] for r in range(h)]
        else:
            vals = [grid[r][w - 1] for r in range(h)]
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
                runs.append((i, j, color))
            i = j
        return runs

    pairs = []
    for side_a, side_b in (("top", "bottom"), ("left", "right")):
        for a0, a1, color_a in edge_runs(side_a):
            for b0, b1, color_b in edge_runs(side_b):
                if color_a == color_b and a1 - a0 == b1 - b0:
                    pairs.append((side_a, side_b, a0, b0, a1 - a0))

    guide_colors = set()
    for side in ("top", "bottom", "left", "right"):
        if side == "top":
            vals = grid[0]
        elif side == "bottom":
            vals = grid[h - 1]
        elif side == "left":
            vals = [grid[r][0] for r in range(h)]
        else:
            vals = [grid[r][w - 1] for r in range(h)]
        guide_colors.update(v for v in vals if v != bg)
    marker_colors = [v for v in counts if v != bg and v not in guide_colors]

    for side_a, side_b, start_a, start_b, length in pairs:
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color in guide_colors or color not in marker_colors:
                    continue

                if side_a in ("top", "bottom"):
                    if start_a <= c < start_a + length:
                        source, offset = side_a, c - start_a
                        partner_start = start_b
                    elif start_b <= c < start_b + length:
                        source, offset = side_b, c - start_b
                        partner_start = start_a
                    else:
                        continue

                    # Continue from marker toward the edge whose bar it aligns with.
                    step = -1 if source == "top" else 1
                    rr = r + step
                    while 0 < rr < h - 1 and grid[rr][c] == bg:
                        out[rr][c] = color
                        rr += step
                    out[r][c] = 4

                    # The corresponding offset from the opposite bar is a full
                    # parallel projection through the interior; markers become 4.
                    partner_col = partner_start + offset
                    for rr in range(1, h - 1):
                        if grid[rr][partner_col] == bg:
                            out[rr][partner_col] = color
                        elif grid[rr][partner_col] not in guide_colors:
                            out[rr][partner_col] = 4
                else:
                    if start_a <= r < start_a + length:
                        source, offset = side_a, r - start_a
                        partner_start = start_b
                    elif start_b <= r < start_b + length:
                        source, offset = side_b, r - start_b
                        partner_start = start_a
                    else:
                        continue

                    step = -1 if source == "left" else 1
                    cc = c + step
                    while 0 < cc < w - 1 and grid[r][cc] == bg:
                        out[r][cc] = color
                        cc += step
                    out[r][c] = 4

                    partner_row = partner_start + offset
                    for cc in range(1, w - 1):
                        if grid[partner_row][cc] == bg:
                            out[partner_row][cc] = color
                        elif grid[partner_row][cc] not in guide_colors:
                            out[partner_row][cc] = 4
    return out
