 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-medium-ws0/frozen/seen-4/play/users/u083/system/state/workspace/programs/task-d1a039f9.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(side):
        vals = (grid[0] if side == "top" else grid[h-1] if side == "bottom"
                else [grid[r][0] for r in range(h)] if side == "left"
                else [grid[r][w-1] for r in range(h)])
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j-i >= 2:
                runs.append((i, j, color))
            i = j
        return runs

    guide_colors = set()
    for side in ("top", "bottom", "left", "right"):
        vals = (grid[0] if side == "top" else grid[h-1] if side == "bottom"
                else [grid[r][0] for r in range(h)] if side == "left"
                else [grid[r][w-1] for r in range(h)])
        guide_colors.update(v for v in vals if v != bg)
    marker_colors = [v for v in counts if v != bg and v not in guide_colors]

    pairs = []
    for a_side, b_side in (("top", "bottom"), ("left", "right")):
        for a0, a1, ac in edge_runs(a_side):
            for b0, b1, bc in edge_runs(b_side):
                if ac == bc and a1-a0 == b1-b0:
                    pairs.append((a_side, b_side, a0, b0, a1-a0))

    for a_side, b_side, a0, b0, n in pairs:
        horizontal = a_side in ("top", "bottom")
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color in guide_colors or color not in marker_colors:
                    continue
                axis = c if horizontal else r
                if a0 <= axis < a0+n:
                    source, offset, other_start = a_side, axis-a0, b0
                elif b0 <= axis < b0+n:
                    source, offset, other_start = b_side, axis-b0, a0
                else:
                    continue

                # Fill the ray from the marker toward its own guide edge.
                if horizontal:
                    step = -1 if source == "top" else 1
                    rr = r + step
                    while 0 < rr < h-1 and grid[rr][c] == bg:
                        out[rr][c] = color
                        rr += step
                    out[r][c] = 4
                    # Corresponding offset from the opposite guide is filled
                    # across the whole interior, preserving the guide bars.
                    pc = other_start + offset
                    for rr in range(1, h-1):
                        if grid[rr][pc] == bg:
                            out[rr][pc] = color
                        elif grid[rr][pc] not in guide_colors:
                            out[rr][pc] = 4
                else:
                    step = -1 if source == "left" else 1
                    cc = c + step
                    while 0 < cc < w-1 and grid[r][cc] == bg:
                        out[r][cc] = color
                        cc += step
                    out[r][c] = 4
                    pr = other_start + offset
                    for cc in range(1, w-1):
                        if grid[pr][cc] == bg:
                            out[pr][cc] = color
                        elif grid[pr][cc] not in guide_colors:
                            out[pr][cc] = 4
    return out
