 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(line):
        found = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            if j - i >= 2:
                found.append((i, j, color))
            i = j
        return found

    # Locate matching guide bars on opposite borders.
    pairs = []
    for side_a, side_b, line_a, line_b in (
        ("top", "bottom", grid[0], grid[-1]),
        ("left", "right", [r[0] for r in grid], [r[-1] for r in grid]),
    ):
        for a, b, color in runs(line_a):
            for x, y, color2 in runs(line_b):
                if color == color2 and b - a == y - x:
                    pairs.append((side_a, side_b, a, x, b - a, color))

    guide_colors = set()
    for side in ("top", "bottom", "left", "right"):
        line = (grid[0] if side == "top" else grid[-1] if side == "bottom"
                else [r[0] for r in grid] if side == "left"
                else [r[-1] for r in grid])
        guide_colors.update(v for v in line if v != bg)
    markers = {v for v in counts if v != bg and v not in guide_colors}

    for side_a, side_b, a, b, length, guide_color in pairs:
        horizontal = side_a == "top"
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color not in markers:
                    continue
                axis = c if horizontal else r
                if a <= axis < a + length:
                    source, offset = side_a, axis - a
                    opposite_start = b
                elif b <= axis < b + length:
                    source, offset = side_b, axis - b
                    opposite_start = a
                else:
                    continue

                # Project the marker along its own axis toward its aligned guide.
                if horizontal:
                    step = -1 if source == "top" else 1
                    rr = r + step
                    while 0 <= rr < h and grid[rr][c] == bg:
                        out[rr][c] = color
                        rr += step
                    other_col = opposite_start + offset
                    for rr in range(h):
                        if grid[rr][other_col] == bg:
                            out[rr][other_col] = color
                else:
                    step = -1 if source == "left" else 1
                    cc = c + step
                    while 0 <= cc < w and grid[r][cc] == bg:
                        out[r][cc] = color
                        cc += step
                    other_row = opposite_start + offset
                    for cc in range(w):
                        if grid[other_row][cc] == bg:
                            out[other_row][cc] = color
                out[r][c] = 4
    return out
