 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_runs(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color = line[i]
            j = i + 1
            while j < len(line) and line[j] == color:
                j += 1
            if j - i >= 2:
                result.append((i, j, color))
            i = j
        return result

    candidates = []
    for sa, sb, la, lb in (
        ("top", "bottom", grid[0], grid[-1]),
        ("left", "right", [row[0] for row in grid], [row[-1] for row in grid]),
    ):
        for a0, a1, ac in edge_runs(la):
            for b0, b1, bc in edge_runs(lb):
                if ac == bc and a1 - a0 == b1 - b0:
                    candidates.append((sa, sb, a0, b0, a1 - a0, ac))
    if not candidates:
        return out

    sa, sb, a0, b0, length, guide = candidates[0]
    guide_colors = {v for v in grid[0] + grid[-1] if v != bg}
    guide_colors |= {row[0] for row in grid if row[0] != bg}
    guide_colors |= {row[-1] for row in grid if row[-1] != bg}
    marker_colors = {v for v in counts if v != bg and v not in guide_colors}

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in marker_colors:
                continue
            axis = c if sa == "top" else r
            if a0 <= axis < a0 + length:
                source, offset, opposite_start = sa, axis - a0, b0
            elif b0 <= axis < b0 + length:
                source, offset, opposite_start = sb, axis - b0, a0
            else:
                continue

            if sa == "top":
                # Ray to the guide edge whose span contains the marker.
                step = -1 if source == "top" else 1
                rr = r + step
                while 0 < rr < h - 1 and grid[rr][c] == bg:
                    out[rr][c] = color
                    rr += step
                out[r][c] = 4
                # Matching offset from the opposite guide projects through
                # the interior, leaving the guide bars intact.
                pc = opposite_start + offset
                for rr in range(1, h - 1):
                    if grid[rr][pc] == bg:
                        out[rr][pc] = color
                    elif grid[rr][pc] not in guide_colors:
                        out[rr][pc] = 4
            else:
                step = -1 if source == "left" else 1
                cc = c + step
                while 0 < cc < w - 1 and grid[r][cc] == bg:
                    out[r][cc] = color
                    cc += step
                out[r][c] = 4
                pr = opposite_start + offset
                for cc in range(1, w - 1):
                    if grid[pr][cc] == bg:
                        out[pr][cc] = color
                    elif grid[pr][cc] not in guide_colors:
                        out[pr][cc] = 4
    return out
